-- Readable blog URLs: /dr/:doctor/blog/:slug instead of the post UUID.
-- The UUID form keeps working (the Edge function 301s it to the slug form).
-- Slugs are generated by a trigger so every creator (admin UI, AI blog writer,
-- staff) gets one without code changes, and stay stable when the title changes.
-- Depends on public.directory_slugify() from 20261027090000_doctor_directory.sql.

ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS slug text;

CREATE OR REPLACE FUNCTION public.blog_post_set_slug()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  base text;
  candidate text;
  n int := 1;
BEGIN
  IF NEW.slug IS NOT NULL AND btrim(NEW.slug) <> '' THEN
    RETURN NEW;
  END IF;

  base := trim(both '-' from left(public.directory_slugify(NEW.title), 80));
  IF base = '' THEN base := 'post'; END IF;

  candidate := base;
  WHILE EXISTS (
    SELECT 1 FROM public.blog_posts p
    WHERE p.doctor_id = NEW.doctor_id AND p.slug = candidate AND p.id <> NEW.id
  ) LOOP
    n := n + 1;
    candidate := base || '-' || n;
  END LOOP;

  NEW.slug := candidate;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS blog_post_set_slug ON public.blog_posts;
CREATE TRIGGER blog_post_set_slug
  BEFORE INSERT OR UPDATE OF slug ON public.blog_posts
  FOR EACH ROW EXECUTE FUNCTION public.blog_post_set_slug();

-- Backfill existing posts without touching updated_at (it feeds sitemap <lastmod>).
ALTER TABLE public.blog_posts DISABLE TRIGGER update_blog_posts_updated_at;
UPDATE public.blog_posts SET slug = '' WHERE slug IS NULL OR btrim(slug) = '';
ALTER TABLE public.blog_posts ENABLE TRIGGER update_blog_posts_updated_at;

CREATE UNIQUE INDEX IF NOT EXISTS idx_blog_posts_doctor_slug
  ON public.blog_posts (doctor_id, slug) WHERE slug IS NOT NULL;
